"""Qwen3-VL conditional generation port with the official vision tower."""

import sys
from pathlib import Path

import torch
from torch import nn
from torch.nn import functional as F

sys.path.append(str(Path(__file__).resolve().parent.parent))
sys.path.append(str(Path(__file__).resolve().parent.parent / "qwen3_model"))

from modeling_qwen3 import Qwen3Model
from configuration_qwen3 import Qwen3Config
from .configuration_qwen3_vl import Qwen3VLConfig
from .vision_modeling_qwen3_vl import Qwen3VLVisionModel


class Qwen3VLForConditionalGeneration(nn.Module):
    """Inject source image and video features at Qwen3-VL placeholder locations."""

    def __init__(self, config: Qwen3VLConfig) -> None:
        """Create visual encoder, Qwen3 text decoder, and LM head.

        Parameters:
            config: Combined Qwen3-VL configuration.
        """
        super().__init__()
        self.config = config
        text_config = Qwen3Config(**config.text_config.__dict__)
        self.visual = Qwen3VLVisionModel(config.vision_config)
        self.model = Qwen3Model(text_config)
        self.lm_head = nn.Linear(text_config.hidden_size, text_config.vocab_size, bias = False)

    def forward(
        self,
        input_ids: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        past_key_values = None,
        use_cache: bool = False,
        pixel_values: torch.Tensor | None = None,
        pixel_values_videos: torch.Tensor | None = None,
        image_grid_thw: torch.Tensor | None = None,
        video_grid_thw: torch.Tensor | None = None,
        labels: torch.Tensor | None = None,
    ) -> torch.Tensor | tuple[torch.Tensor, torch.Tensor]:
        """Return logits and optional causal loss for official packed visual patches.

        Parameters:
            input_ids: Text IDs containing enough image/video placeholders when media is supplied.
            attention_mask: Optional text padding mask.
            past_key_values: Optional Qwen3 K/V cache for incremental decoding.
            use_cache: Whether the text decoder updates and returns its K/V cache.
            pixel_values: Flattened processor patches shaped ``[patches, C * T * P * P]``.
            pixel_values_videos: Flattened video processor patches.
            image_grid_thw: Image temporal-height-width patch grids for the vision tower.
            video_grid_thw: Video temporal-height-width patch grids for the vision tower.
            labels: Optional causal language-model targets.
        """
        embeddings = self.model.embed_tokens(input_ids)
        if pixel_values is not None:
            if image_grid_thw is None:
                raise ValueError("image_grid_thw is required with packed Qwen3-VL pixel_values")
            embeddings = self._inject_visual_features(
                embeddings,
                input_ids == self.config.image_token_id,
                self.visual(pixel_values, image_grid_thw).pooler_output,
                "image",
            )
        if pixel_values_videos is not None:
            if video_grid_thw is None:
                raise ValueError("video_grid_thw is required with packed Qwen3-VL pixel_values_videos")
            embeddings = self._inject_visual_features(
                embeddings,
                input_ids == self.config.video_token_id,
                self.visual(pixel_values_videos, video_grid_thw).pooler_output,
                "video",
            )
        outputs = self.model(
            inputs_embeds = embeddings,
            attention_mask = attention_mask,
            past_key_values = past_key_values,
            use_cache = use_cache,
        )
        logits = self.lm_head(outputs.last_hidden_state)
        if labels is None:
            return logits
        loss = F.cross_entropy(logits[:, :-1].reshape(-1, logits.shape[-1]), labels[:, 1:].reshape(-1), ignore_index = -100)
        return logits, loss

    @staticmethod
    def _inject_visual_features(
        embeddings: torch.Tensor,
        positions: torch.Tensor,
        visual_tokens: torch.Tensor,
        modality: str,
    ) -> torch.Tensor:
        """Replace one modality's source placeholder embeddings.

        Parameters:
            embeddings: Token embeddings before visual replacement.
            positions: Boolean placeholder positions for one modality.
            visual_tokens: Merged packed vision features.
            modality: Name used in a clear source-token-count error.
        """
        if positions.sum().item() != visual_tokens.shape[0]:
            raise ValueError(f"{modality}_token_id count must equal the number of visual patch tokens")
        updated_embeddings = embeddings.clone()
        updated_embeddings[positions] = visual_tokens.to(updated_embeddings)
        return updated_embeddings
